template <class T1, class T2>

constexpr bool

operator==(const allocator<T1> &lhs, const allocator<T2> &rhs) noexcept;

examples.code:
#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::allocator<int> allocator, other;
    assert(allocator == other);
    int *storage = allocator.allocate(1);
    assert(allocator.address(*storage) == storage);
    allocator.construct(storage, 42);
    assert(*storage == 42);
    assert(allocator.max_size() >= 1);
    allocator.destroy(storage);
    allocator.deallocate(storage, 1);
}
